// js/util/audioManager.js
import { settingsManager } from '../game/settingsManager.js';
import { AREAS } from '../main.js';

let audioContext = null;
let masterGain = null;
let musicGain = null;
let musicFilter = null;
let sfxGain = null;
let sfxFilter = null;

const buffers = new Map();
const loadPromises = new Map();

// Helper to get or create context
function getAudioContext() {
  if (audioContext) return audioContext;
  
  // Check browser support
  const Ctx = window.AudioContext || window.webkitAudioContext;
  if (!Ctx) return null;

  audioContext = new Ctx();
  masterGain = audioContext.createGain();
  masterGain.connect(audioContext.destination);
  
  // Initial gain setup
  masterGain.gain.value = 1.0; 

  // Music Pipeline: Source -> Filter -> MusicGain -> MasterGain
  musicGain = audioContext.createGain();
  musicGain.gain.value = 1.0;
  musicGain.connect(masterGain);

  musicFilter = audioContext.createBiquadFilter();
  musicFilter.type = 'lowpass';
  musicFilter.frequency.value = 22050; // Open by default
  musicFilter.Q.value = 1; // Slight resonance or neutral
  musicFilter.connect(musicGain);

  // SFX Pipeline: Source -> Filter -> SFXGain -> MasterGain
  sfxGain = audioContext.createGain();
  sfxGain.gain.value = 1.0;
  sfxGain.connect(masterGain);

  sfxFilter = audioContext.createBiquadFilter();
  sfxFilter.type = "lowpass";
  sfxFilter.frequency.value = 22050; // Open by default
  sfxFilter.Q.value = 1; // Slight resonance or neutral
  sfxFilter.connect(sfxGain);
  
  return audioContext;
}

export function initAudio() {
    getAudioContext();
    
    // Set initial volume based on settings
    const initialMusicVolume = settingsManager.get('music_volume');
    if (initialMusicVolume !== false) {
        setMusicVolume(initialMusicVolume);
    }
    const initialMasterVolume = settingsManager.get('master_volume');
    if (initialMasterVolume !== false) {
        setMasterVolume(initialMasterVolume);
    }
    
    // Set initial sfx volume
    const initialSfxVolume = settingsManager.get('sfx_volume');
    if (initialSfxVolume !== false && initialSfxVolume !== undefined) {
        setSfxVolume(initialSfxVolume);
    }

    // Subscribe to future volume changes
    settingsManager.subscribe('music_volume', (val) => {
        setMusicVolume(val);
    });
    settingsManager.subscribe('master_volume', (val) => {
        setMasterVolume(val);
    });
    settingsManager.subscribe('sfx_volume', (val) => {
        setSfxVolume(val);
    });
}

// "Warm" the context on user interaction
function warm() {
  if (audioContext && audioContext.state === 'suspended') {
    audioContext.resume().catch(() => {});
  }
}

if (typeof window !== 'undefined') {
  ['pointerdown', 'touchstart', 'click', 'keydown'].forEach(evt => {
    window.addEventListener(evt, warm, { capture: true, passive: true });
  });
}

/**
 * Loads and decodes audio from a URL.
 * @param {string} src - The URL of the audio file.
 * @returns {Promise<AudioBuffer|null>}
 */
export async function loadAudio(src) {
  const ctx = getAudioContext();
  if (!ctx) return null; // No Web Audio support

  // Normalize URL
  const url = new URL(src, document.baseURI).href;

  if (buffers.has(url)) return buffers.get(url);
  if (loadPromises.has(url)) return loadPromises.get(url);

  const promise = (async () => {
    try {
      const resp = await fetch(url);
      if (!resp.ok) throw new Error(`Failed to fetch ${url}`);
      const arrayBuffer = await resp.arrayBuffer();
      const decoded = await ctx.decodeAudioData(arrayBuffer);
      buffers.set(url, decoded);
      return decoded;
    } catch (e) {
      console.warn('[audioManager] Load failed', src, e);
      return null;
    } finally {
      loadPromises.delete(url);
    }
  })();

  loadPromises.set(url, promise);
  return promise;
}

/**
 * Plays audio.
 * @param {string} src - The URL of the audio file.
 * @param {object} options
 * @param {number} [options.volume=1.0] - Playback volume (0.0 to 1.0).
 * @param {number} [options.detune=0] - Detune in cents.
 * @param {number} [options.playbackRate=1.0] - Playback rate.
 * @param {boolean} [options.loop=false] - Whether to loop.
 * @param {string} [options.type='sfx'] - 'sfx', 'music', or 'spawn_vessel'.
 */
export function playAudio(src, { volume = 1.0, detune = 0, playbackRate = 1.0, loop = false, type = 'sfx', fadeDuration = 0 } = {}) {
  if (window.currentArea === AREAS.JAIL || window.__duplicateInstanceDetected) return;

  if (typeof window !== 'undefined' && typeof window.isMutedByVault === 'function' && window.isMutedByVault()) {
    const isOpeningSfx = src.includes('opening.ogg');
    const isCoinSfx = src.includes('coin_pickup_size5.ogg');
    if (!isOpeningSfx && !isCoinSfx) {
      return null;
    }
  }
 
  let isSpawnVessel = false;
  if (type === 'spawn_vessel') {
      isSpawnVessel = true;
      const spawnVesselVolumeSetting = settingsManager.get('spawn_vessel_volume');
      volume = volume * (spawnVesselVolumeSetting / 100);
      type = 'sfx';
  }

  const ctx = getAudioContext();
  const url = new URL(src, document.baseURI).href;
  
  // Try Web Audio first
  if (ctx) {
    if (ctx.state === 'suspended' && !document.hidden) ctx.resume().catch(()=>{});
    
    const buffer = buffers.get(url);
    if (buffer) {
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.detune.value = detune;
        source.playbackRate.value = playbackRate;
        source.loop = loop;
        
        const gainNode = ctx.createGain();
        
        if (fadeDuration > 0) {
            gainNode.gain.value = 0;
            try {
                const now = ctx.currentTime;
                gainNode.gain.setValueAtTime(0, now);
                gainNode.gain.linearRampToValueAtTime(volume, now + fadeDuration);
            } catch (e) {
                gainNode.gain.value = volume;
            }
        } else {
            gainNode.gain.value = volume;
        }
        
        source.connect(gainNode);
        
        // Routing logic
        if (type === 'music') {
            gainNode.connect(musicFilter);
        } else if (type === "sfx") {
            gainNode.connect(sfxFilter);
        } else {
            gainNode.connect(masterGain);
        }

        source.start(0);
        
        let stopTimeout = null;
        
        return {
            stop: (fadeOutDuration = 0) => {
                if (stopTimeout) clearTimeout(stopTimeout);
                if (fadeOutDuration > 0) {
                    try {
                        const now = ctx.currentTime;
                        const currentVol = gainNode.gain.value;
                        gainNode.gain.cancelScheduledValues(now);
                        gainNode.gain.setValueAtTime(currentVol, now);
                        gainNode.gain.linearRampToValueAtTime(0, now + fadeOutDuration);
                        stopTimeout = setTimeout(() => {
                            try { source.stop(); } catch {}
                        }, fadeOutDuration * 1000);
                        return;
                    } catch (e) {}
                }
                try { source.stop(); } catch {}
            },
            source,
            gainNode,
            setVolume: (newVolumeBase) => {
                let actualVolume = newVolumeBase;
                if (isSpawnVessel) {
                    const spawnVesselVolumeSetting = settingsManager.get('spawn_vessel_volume');
                    actualVolume = actualVolume * (spawnVesselVolumeSetting / 100);
                }
                try {
                    const now = ctx.currentTime;
                    gainNode.gain.cancelScheduledValues(now);
                    gainNode.gain.setValueAtTime(actualVolume, now);
                } catch (e) {
                    gainNode.gain.value = actualVolume;
                }
            },
            element: null // No HTML5 audio element
        };
    } else {
        // Trigger load for next time
        loadAudio(src);
    }
  }

  // Fallback: HTML5 Audio (if Web Audio unavailable or buffer not loaded yet)
  // Note: This might still have latency, but it's a fallback.
  // Note: Fallback does NOT support the filter effect as it bypasses Web Audio graph.
  try {
      const a = new Audio(url);
      
      const masterVolumeSetting = settingsManager.get('master_volume');
      let finalVolume = masterVolumeSetting !== undefined && masterVolumeSetting !== null 
          ? volume * (masterVolumeSetting / 100) 
          : volume;

      // HTML5 Audio fallback doesn't use the Web Audio global gains, so we need to multiply them here.
      if (type === 'music') {
          const musicVolumeSetting = settingsManager.get('music_volume');
          if (musicVolumeSetting !== undefined && musicVolumeSetting !== null) {
              finalVolume = finalVolume * (musicVolumeSetting / 100);
          }
      } else if (type === 'sfx') {
          const sfxVolumeSetting = settingsManager.get('sfx_volume');
          if (sfxVolumeSetting !== undefined && sfxVolumeSetting !== null) {
              finalVolume = finalVolume * (sfxVolumeSetting / 100);
          }
      }

      let fadeInterval = null;
      let stopTimeout = null;
      
      if (fadeDuration > 0) {
          a.volume = 0;
          const steps = 20;
          const stepTime = (fadeDuration * 1000) / steps;
          const volStep = finalVolume / steps;
          let currentVol = 0;
          
          fadeInterval = setInterval(() => {
              currentVol += volStep;
              if (currentVol >= finalVolume) {
                  currentVol = finalVolume;
                  clearInterval(fadeInterval);
              }
              a.volume = currentVol;
          }, stepTime);
      } else {
          a.volume = finalVolume;
      }
      
      if (typeof a.playbackRate !== 'undefined') {
          a.playbackRate = playbackRate;
      }
      a.loop = loop;
      a.play().catch(() => {});
      
      return {
          stop: (fadeOutDuration = 0) => {
              if (fadeInterval) clearInterval(fadeInterval);
              if (stopTimeout) clearTimeout(stopTimeout);
              
              if (fadeOutDuration > 0) {
                  const steps = 20;
                  const stepTime = (fadeOutDuration * 1000) / steps;
                  const volStep = a.volume / steps;
                  let currentVol = a.volume;
                  
                  fadeInterval = setInterval(() => {
                      currentVol -= volStep;
                      if (currentVol <= 0) {
                          currentVol = 0;
                          clearInterval(fadeInterval);
                          try { a.pause(); a.currentTime = 0; } catch {}
                      }
                      try { a.volume = currentVol; } catch {}
                  }, stepTime);
                  return;
              }
              try { a.pause(); a.currentTime = 0; } catch {}
          },
          setVolume: (newVolumeBase) => {
              let actualVolume = newVolumeBase;
              if (isSpawnVessel) {
                  const spawnVesselVolumeSetting = settingsManager.get('spawn_vessel_volume');
                  actualVolume = actualVolume * (spawnVesselVolumeSetting / 100);
              }
              const mvs = settingsManager.get('master_volume');
              let finalVol = mvs !== undefined && mvs !== null ? actualVolume * (mvs / 100) : actualVolume;
              if (type === 'music') {
                  const musv = settingsManager.get('music_volume');
                  if (musv !== undefined && musv !== null) finalVol = finalVol * (musv / 100);
              } else if (type === 'sfx') {
                  const sfxv = settingsManager.get('sfx_volume');
                  if (sfxv !== undefined && sfxv !== null) finalVol = finalVol * (sfxv / 100);
              }
              if (fadeInterval) {
                  clearInterval(fadeInterval);
                  fadeInterval = null;
              }
              try { a.volume = finalVol; } catch {}
          },
          element: a
      };
  } catch(e) {
      console.warn('[audioManager] Fallback play failed', e);
  }
  return null;
}

// Support for preloading from main.js (compatible signature if needed, or just use loadAudio)
export function registerPreloadedBuffer(src, buffer) {
  const url = new URL(src, document.baseURI).href;
  buffers.set(url, buffer);
}

export function setAudioSuspended(suspended) {
  if (audioContext) {
    if (suspended) {
      if (audioContext.state === 'running') audioContext.suspend().catch(()=>{});
    } else {
      if (audioContext.state === 'suspended') audioContext.resume().catch(()=>{});
    }
  }
}

export function setMasterVolume(volumePercentage) {
    if (!masterGain) return;
    
    // Map 0-100 to 0.0-1.0
    const gainValue = Math.max(0, Math.min(100, volumePercentage)) / 100.0;
    
    try {
        const now = audioContext.currentTime;
        masterGain.gain.cancelScheduledValues(now);
        masterGain.gain.setValueAtTime(gainValue, now);
    } catch {
        masterGain.gain.value = gainValue;
    }
}

export function setMusicVolume(volumePercentage) {
    if (!musicGain) return;
    
    // Map 0-100 to 0.0-1.0
    const gainValue = Math.max(0, Math.min(100, volumePercentage)) / 100.0;
    
    try {
        const now = audioContext.currentTime;
        musicGain.gain.cancelScheduledValues(now);
        musicGain.gain.setValueAtTime(gainValue, now);
    } catch {
        musicGain.gain.value = gainValue;
    }
}

export function setSfxVolume(volumePercentage) {
    if (!sfxGain) return;
    
    // Map 0-100 to 0.0-1.0
    const gainValue = Math.max(0, Math.min(100, volumePercentage)) / 100.0;
    
    try {
        const now = audioContext.currentTime;
        sfxGain.gain.cancelScheduledValues(now);
        sfxGain.gain.setValueAtTime(gainValue, now);
    } catch {
        sfxGain.gain.value = gainValue;
    }
}

let isUnderwaterState = false;
let drownInstances = 0;

export function setAudioUnderwater(underwater) {
    isUnderwaterState = underwater;
    if (!musicFilter && !sfxFilter) return;
    if (drownInstances > 0) return;
    const frequency = underwater ? 600 : 22050;
    try {
        const now = audioContext.currentTime;
        if (musicFilter) {
            musicFilter.frequency.cancelScheduledValues(now);
            musicFilter.frequency.setValueAtTime(frequency, now);
        }
        if (sfxFilter) {
            sfxFilter.frequency.cancelScheduledValues(now);
            sfxFilter.frequency.setValueAtTime(frequency, now);
        }
    } catch {
        if (musicFilter) {
            try {
                musicFilter.frequency.cancelScheduledValues(audioContext.currentTime);
                musicFilter.frequency.value = frequency;
            } catch(e) {}
        }
        if (sfxFilter) {
            try {
                sfxFilter.frequency.cancelScheduledValues(audioContext.currentTime);
                sfxFilter.frequency.value = frequency;
            } catch(e) {}
        }
    }
}

export function applyAudioDrownEffect(durationInSeconds) {
    if (!musicFilter && !sfxFilter) return;
    drownInstances++;
    try {
        const now = audioContext.currentTime;
        const baseFreq = isUnderwaterState ? 600 : 22050;
        
        let currentMusicFreq = musicFilter ? musicFilter.frequency.value : baseFreq;
        let currentSfxFreq = sfxFilter ? sfxFilter.frequency.value : baseFreq;

        const intensityFactor = Math.pow(0.5, drownInstances - 1);
        const midFreq = isUnderwaterState ? Math.max(10, 300 * intensityFactor) : Math.max(10, 2000 * intensityFactor);
        const targetFreq = Math.max(10, 30 * intensityFactor);
        
        if (musicFilter) {
            musicFilter.frequency.cancelScheduledValues(now);
            musicFilter.frequency.setValueAtTime(currentMusicFreq, now);
            musicFilter.frequency.linearRampToValueAtTime(midFreq, now + 1.0);
            musicFilter.frequency.linearRampToValueAtTime(targetFreq, now + durationInSeconds);
        }
        if (sfxFilter) {
            sfxFilter.frequency.cancelScheduledValues(now);
            sfxFilter.frequency.setValueAtTime(currentSfxFreq, now);
            sfxFilter.frequency.linearRampToValueAtTime(midFreq, now + 1.0);
            sfxFilter.frequency.linearRampToValueAtTime(targetFreq, now + durationInSeconds);
        }
    } catch {
        if (musicFilter) {
            try {
                musicFilter.frequency.cancelScheduledValues(audioContext.currentTime);
                musicFilter.frequency.value = 50;
            } catch(e) {}
        }
        if (sfxFilter) {
            try {
                sfxFilter.frequency.cancelScheduledValues(audioContext.currentTime);
                sfxFilter.frequency.value = 50;
            } catch(e) {}
        }
    }
}

export function removeAudioDrownEffect() {
    if (drownInstances > 0) drownInstances--;
    if (drownInstances === 0) {
        setAudioUnderwater(isUnderwaterState);
    }
}
