const LOG10_EXP_0_2 = 0.08685889638; // log10(e^0.2)
const TSUNAMI_NERF_KEY = (slot) => `ccc:surge:tsunamiNerf:${slot}`;
const TSUNAMI_UNLOCKED_KEY = (slot) => `ccc:unlock:tsunami:${slot}`;
